DATABASE_URL = os.environ.get("FUJIN_LOCAL_DATABASE_URL", "sqlite+pysqlite:////tmp/fujin-local.db")
SQLITE_BUSY_TIMEOUT_SECONDS = max(1, int(os.environ.get("FUJIN_LOCAL_SQLITE_BUSY_TIMEOUT_SECONDS", "30")))
SQLITE_LOCK_RETRY_ATTEMPTS = max(0, int(os.environ.get("FUJIN_LOCAL_SQLITE_LOCK_RETRY_ATTEMPTS", "3")))
_sqlite_database = DATABASE_URL.startswith("sqlite")
engine = create_engine(
    DATABASE_URL,
    pool_pre_ping=True,
    connect_args={"timeout": SQLITE_BUSY_TIMEOUT_SECONDS} if _sqlite_database else {},
)


def sqlite_locked(error: BaseException) -> bool:
    """Return whether SQLite rejected a request due to transient writer contention."""
    return _sqlite_database and "database is locked" in str(error).lower()


if _sqlite_database:
    @event.listens_for(engine, "connect")
    def configure_sqlite_connection(dbapi_connection, _connection_record) -> None:
        # WAL lets readers coexist with the one SQLite writer. The timeout
        # protects short write bursts generated by concurrent Raijus.
        cursor = dbapi_connection.cursor()
        cursor.execute("PRAGMA journal_mode=WAL")
        cursor.execute(f"PRAGMA busy_timeout={SQLITE_BUSY_TIMEOUT_SECONDS * 1000}")
        cursor.execute("PRAGMA synchronous=NORMAL")
        cursor.close()

    @event.listens_for(engine, "do_execute", retval=True)
    def retry_transient_sqlite_statement(cursor, statement, parameters, _context):
        # This retry occurs before SQLAlchemy changes transaction state, so
        # unlike retrying session.commit() it cannot lose pending mutations.
        for attempt in range(SQLITE_LOCK_RETRY_ATTEMPTS + 1):
            try:
                cursor.execute(statement, parameters)
                return True
            except sqlite3.OperationalError as error:
                if not sqlite_locked(error) or attempt >= SQLITE_LOCK_RETRY_ATTEMPTS:
                    raise
                sleep(0.05 * (2 ** attempt))
SessionLocal = sessionmaker(bind=engine)
