@app.put("/api/local/s3-buckets/{bucket_id}/restore-policy")
def update_s3_restore_policy(bucket_id: str, payload: S3RestorePolicyUpdate,
                             request: Request, session: Session = Depends(get_session)) -> dict:
    """Change only the policy read by restore requests submitted after this update.

    Every LocalRestore has already persisted its own available_at and expiry_at.
    Updating the bucket policy must never recalculate those existing timestamps.
    """
    require_admin(request)
    bucket = session.get(LocalS3Bucket, bucket_id)
    if not bucket or bucket.deleted_at:
        raise HTTPException(404, "S3 bucket not found")
    try:
        previous = normalized_restore_policy(json.loads(bucket.restore_policy_json or "{}"))
        updated = normalized_restore_policy(payload.restore_policy)
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise HTTPException(422, str(error)) from error
    if previous == updated:
        return {
            "id": bucket.id, "name": bucket.name, "restore_policy": updated,
            "changed": False, "effective_for": "future_restore_requests_only",
        }
    bucket.restore_policy_json = json.dumps(updated, sort_keys=True)
    identifier = audit(
        session, "LOCAL_S3_RESTORE_POLICY_UPDATED", 200, bucket.name,
        detail=(f"previous={json.dumps(previous, sort_keys=True)}; "
                f"updated={json.dumps(updated, sort_keys=True)}; "
                "existing restores retain their persisted availability and expiry timestamps"),
    )
    session.commit()
    return {
        "id": bucket.id, "name": bucket.name, "restore_policy": updated,
        "changed": True, "request_id": identifier,
        "effective_for": "future_restore_requests_only",
    }


